# Define masks as above and compare dihedral similarity test p1
masks={
'd1':{(0,0),(0,4),(1,4),(2,3),(3,2),(4,1)},
'd2':{(0,2),(1,2),(2,0),(2,2),(3,2),(4,2)},
'd3':{(0,0),(1,1),(2,2),(3,3),(4,0),(4,4)},
'd4':{(0,2),(2,0),(2,1),(2,2),(2,3),(2,4)},
'test':{(0,2),(0,4),(1,2),(2,2),(2,3),(2,4)}}
def transforms(s):
 out=[]
 for refl in [False,True]:
  for k in range(4):
   t=set()
   for r,c in s:
    if refl:c=4-c
    for _ in range(k):r,c=c,4-r
    t.add((r,c))
   out.append(t)
 return out
for name,s in masks.items():
 if name=='test':continue
 vals=[]
 for i,t in enumerate(transforms(s)):
  vals.append((len(t&masks['test']),i,t))
 best=max(vals,key=lambda a:a[0])
 print(name,'best intersect',best[0], 'transform index',best[1], 'target?',best[2])

